import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    .reg .u64 %rd<16>;
    .reg .u32 %r<48>;
    .reg .f32 %f<10>;
    .reg .pred %p<8>;

    .shared .align 4 .b8 As[1024];
    .shared .align 4 .b8 Bs[1024];

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [N];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r2, %tid.x;    // tx
    mov.u32 %r3, %tid.y;    // ty
    mov.u32 %r4, %ctaid.x;  // bx
    mov.u32 %r5, %ctaid.y;  // by

    mov.u32 %r6, 16;

    mul.lo.s32 %r7, %r5, %r6;
    add.s32 %r8, %r7, %r3;    // row = by*16 + ty

    mul.lo.s32 %r9, %r4, %r6;
    add.s32 %r10, %r9, %r2;   // col = bx*16 + tx

    setp.ge.s32 %p1, %r8, %r1;
    setp.ge.s32 %p2, %r10, %r1;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    shr.u32 %r11, %r1, 4;    // numTiles = N / 16

    mov.f32 %f1, 0f00000000; // acc

    mov.u32 %r12, 0;         // t

LOOP_START:
    setp.ge.s32 %p4, %r12, %r11;
    @%p4 bra LOOP_END;

    mul.lo.s32 %r13, %r12, %r6;   // k0 = t*16

    mul.lo.s32 %r14, %r8, %r1;    // row*N
    add.s32 %r15, %r14, %r13;
    add.s32 %r15, %r15, %r2;      // Aoff = row*N + k0 + tx

    add.s32 %r16, %r13, %r3;      // k0+ty
    mul.lo.s32 %r17, %r16, %r1;
    add.s32 %r17, %r17, %r10;     // Boff = (k0+ty)*N + col

    cvt.s64.s32 %rd4, %r15;
    mul.lo.s64 %rd4, %rd4, 4;
    add.s64 %rd5, %rd1, %rd4;
    ld.global.f32 %f2, [%rd5];

    cvt.s64.s32 %rd6, %r17;
    mul.lo.s64 %rd6, %rd6, 4;
    add.s64 %rd7, %rd2, %rd6;
    ld.global.f32 %f3, [%rd7];

    mul.lo.s32 %r18, %r3, %r6;
    add.s32 %r18, %r18, %r2;
    mul.lo.s32 %r19, %r18, 4;

    mov.u32 %r20, As;
    add.s32 %r20, %r20, %r19;
    st.shared.f32 [%r20], %f2;

    mov.u32 %r21, Bs;
    add.s32 %r21, %r21, %r19;
    st.shared.f32 [%r21], %f3;

    bar.sync 0;

    mov.u32 %r22, 0;

INNER_LOOP:
    setp.ge.s32 %p5, %r22, %r6;
    @%p5 bra INNER_END;

    mul.lo.s32 %r23, %r3, %r6;
    add.s32 %r23, %r23, %r22;
    mul.lo.s32 %r23, %r23, 4;
    mov.u32 %r24, As;
    add.s32 %r24, %r24, %r23;
    ld.shared.f32 %f4, [%r24];

    mul.lo.s32 %r25, %r22, %r6;
    add.s32 %r25, %r25, %r2;
    mul.lo.s32 %r25, %r25, 4;
    mov.u32 %r26, Bs;
    add.s32 %r26, %r26, %r25;
    ld.shared.f32 %f5, [%r26];

    fma.rn.f32 %f1, %f4, %f5, %f1;

    add.s32 %r22, %r22, 1;
    bra INNER_LOOP;

INNER_END:
    bar.sync 0;

    add.s32 %r12, %r12, 1;
    bra LOOP_START;

LOOP_END:
    mul.lo.s32 %r27, %r8, %r1;
    add.s32 %r27, %r27, %r10;
    cvt.s64.s32 %rd8, %r27;
    mul.lo.s64 %rd8, %rd8, 4;
    add.s64 %rd9, %rd3, %rd8;
    st.global.f32 [%rd9], %f1;

DONE:
    ret;
