_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.shape == B.shape, "A and B must be square matrices of the same size"
        assert A.dtype == torch.float32 and B.dtype == torch.float32
        assert A.is_cuda and B.is_cuda

        N = A.shape[0]
        C = torch.empty((N, N), device=A.device, dtype=A.dtype)

        module = _get_ptx_module()

        block = (16, 16, 1)
        grid = ((N + 15) // 16, (N + 15) // 16, 1)

        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

